async function c(r,t={}){try{const e=await(await fetch(r,{headers:{"Content-Type":"application/json",...t.headers},...t})).json();if(e&&typeof e.code=="number")if(e.code===200){const s={success:!0,message:e.message};return e.data!=null&&(typeof e.data=="object"&&!Array.isArray(e.data)?(s.data=e.data,Object.assign(s,e.data)):s.data=e.data),s}else return{success:!1,message:e.message||"请求失败"};return e}catch(a){return console.error("Request failed:",a),{success:!1,message:"网络错误: "+a.message}}}export{c as r};
